(1853,'1781421494788',NULL,'1781421436103-159','سلام',0,'[{\"role\":\"user\",\"content\":\"سلام\",\"timestamp\":\"2026-06-14T07:18:19.900Z\"},{\"role\":\"assistant\",\"content\":\"خطا از سرویس مدل دریافت شد.\",\"timestamp\":\"2026-06-14T07:18:20.105Z\"},{\"role\":\"user\",\"content\":\"hi\",\"timestamp\":\"2026-06-14T07:21:39.918Z\"},{\"role\":\"assistant\",\"content\":\"من دانوآ هستم، یک دوست مهربان که اینجا هستم تا با هم کلی چیزهای جدید و هیجان‌انگیز رو کشف کنیم. 🌟\\n\\nامروز دوست داری در مورد چی با هم صحبت کنیم یا چی یاد بگیریم؟\",\"timestamp\":\"2026-06-14T07:21:44.112Z\"},{\"role\":\"user\",\"content\":\"🎨 درخواست ساخت عکس: موز زنده\",\"timestamp\":\"2026-06-14T07:22:37.442Z\"},{\"role\":\"assistant\",\"content\":\"🎨 در حال ساخت عکس... لطفاً صبر کن\",\"timestamp\":\"2026-06-14T07:22:37.442Z\"},{\"role\":\"user\",\"content\":\"🎨 درخواست ساخت عکس: موز قرمز\",\"timestamp\":\"2026-06-14T07:38:24.705Z\"},{\"role\":\"assistant\",\"content\":\"🎨 در حال ساخت عکس... لطفاً صبر کن\",\"timestamp\":\"2026-06-14T07:38:24.705Z\"}]','2026-06-14 07:17:16','2026-06-14 07:39:48'),
